"use strict";
import { createContext, useContext, useState } from "react";
export const BorrowContext = createContext(null);
export const BorrowContextProvider = ({ children }) => {
  const [activeTab, setActiveTab] = useState("Markets");
  const [transactionStep, setTransactionStep] = useState("idle");
  const [transactionType, setTransactionType] = useState("borrow");
  const [selectedPosition, setSelectedPosition] = useState(null);
  const [collateralAmount, setCollateralAmount] = useState("");
  const [borrowAmount, setBorrowAmount] = useState("");
  const openTransaction = (position, type, initialStep = "input") => {
    setSelectedPosition(position);
    setTransactionType(type);
    setTransactionStep(initialStep);
  };
  const closeTransaction = () => {
    setTransactionStep("idle");
    setCollateralAmount("");
    setBorrowAmount("");
    setSelectedPosition(null);
  };
  return <BorrowContext.Provider
    value={{
      activeTab,
      setActiveTab,
      transactionStep,
      setTransactionStep,
      transactionType,
      setTransactionType,
      selectedPosition,
      setSelectedPosition,
      collateralAmount,
      setCollateralAmount,
      borrowAmount,
      setBorrowAmount,
      openTransaction,
      closeTransaction
    }}
  >
      {children}
    </BorrowContext.Provider>;
};
export const useBorrowContext = () => {
  const context = useContext(BorrowContext);
  if (!context) {
    throw new Error("useBorrowContext must be used within a BorrowContextProvider");
  }
  return context;
};
