import { ArrowUpRight, HelpCircle, Shield, X } from "react-feather";
import { Button, Flex, Text, styled as uiStyled, useSporeColors } from "ui/src";
import { Modal } from "uniswap/src/components/modals/Modal";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { useBorrowContext } from "../ContextProvider";
const CloseIcon = uiStyled(Flex, {
  cursor: "pointer",
  padding: "$spacing8",
  borderRadius: "$roundedFull",
  hoverStyle: { backgroundColor: "$surface2" }
});
const ModalHeader = uiStyled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing24"
});
const InfoCard = uiStyled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing24",
  flexDirection: "column",
  gap: "$spacing12",
  width: "100%",
  marginBottom: "$spacing24"
});
const InfoRow = uiStyled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%"
});
const PrimaryActionButton = uiStyled(Button, {
  py: "$spacing20"
});
const OverlappingLogos = uiStyled(Flex, {
  flexDirection: "row",
  position: "relative",
  width: 64,
  height: 40
});
const LogoWrapper = uiStyled(Flex, {
  position: "absolute",
  borderRadius: "$roundedFull",
  borderWidth: 2,
  borderColor: "$surface2",
  overflow: "hidden"
});
const Badge = uiStyled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  px: "$spacing8",
  py: "$spacing2",
  alignItems: "center",
  justifyContent: "center"
});
const Divider = uiStyled(Flex, {
  height: 1,
  backgroundColor: "$surface3",
  width: "100%",
  my: "$spacing4"
});
export default function AutoDeleveragePopupModal({
  position,
  isOpen,
  onClose
}) {
  const { setTransactionStep, closeTransaction } = useBorrowContext();
  const colors = useSporeColors();
  if (!position) return null;
  const collateralToken = position.collateral.token;
  const borrowToken = position.loan.token;
  const liquidationLtv = 62.5;
  const autoDeleverageLtv = 56.25;
  const handleConfirm = () => {
    setTransactionStep("review");
  };
  const handleClose = () => {
    onClose();
  };
  return <Modal
    name={"AutoDeleveragePopupModal"}
    isModalOpen={isOpen}
    onClose={handleClose}
    backgroundColor={colors.surface1.val}
    maxWidth={480}
    padding="$spacing24"
  >
      {
    /* Header */
  }
      <ModalHeader>
        <Text variant="heading2" color="$neutral1">
          Enable Auto-Deleverage
        </Text>
        <CloseIcon onPress={handleClose}>
          <X size={24} color={colors.neutral2.val} />
        </CloseIcon>
      </ModalHeader>

      <Text variant="body3" color="$neutral2" mb="$spacing24" lineHeight={20}>
        Auto-Deleverage is a feature designed to reduce the risk of full liquidation. When enabled, if your LTV exceeds
        a pre-set threshold, a portion of your position may be closed to bring it back to safer levels. This mechanism
        relies on on-chain liquidators and may not keep up with rapid market movements.
      </Text>

      {
    /* Info Card */
  }
      <InfoCard>
        <Flex flexDirection="row" alignItems="center" gap="$gap16" mb="$spacing8">
          <OverlappingLogos>
            <LogoWrapper left={0} zIndex={2}>
              <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.name ?? ""}
    images={[getTokenLogoUrl(collateralToken.id) || void 0]}
    size={40}
  />
            </LogoWrapper>
            <LogoWrapper left={24} zIndex={1}>
              <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={borrowToken.symbol}
    tokenName={borrowToken.name ?? ""}
    images={[getTokenLogoUrl(borrowToken.id) || void 0]}
    size={40}
  />
            </LogoWrapper>
          </OverlappingLogos>
          <Flex flexDirection="column" gap="$gap4">
            <Text variant="heading3" color="$neutral1">
              {collateralToken.symbol}/{borrowToken.symbol}
            </Text>
            <Flex flexDirection="row" gap="$gap8" alignItems="center">
              <Badge>
                <Text variant="body4" color="$neutral2">
                  {liquidationLtv}%
                </Text>
              </Badge>
              <ArrowUpRight size={14} color={colors.neutral2.val} />
            </Flex>
          </Flex>
        </Flex>

        <Divider />

        <InfoRow>
          <Flex flexDirection="row" alignItems="center" gap="$gap8">
            <Text variant="body3" color="$neutral2">
              Auto Deleverage Liq. LTV
            </Text>
            <HelpCircle size={16} color={colors.neutral3.val} />
          </Flex>
          <Flex flexDirection="row" alignItems="center" gap="$gap8">
            <Shield size={16} color={colors.accent1.val} />
            <Text variant="heading3" color="$neutral1">
              {autoDeleverageLtv}%
            </Text>
          </Flex>
        </InfoRow>

        <InfoRow>
          <Text variant="body3" color="$neutral2">
            Liquidation LTV
          </Text>
          <Text variant="body3" color="$neutral1">
            {liquidationLtv}%
          </Text>
        </InfoRow>
      </InfoCard>

      <Text variant="body4" color="$neutral3" textAlign="center" mb="$spacing24" px="$spacing12">
        By using this feature, you agree to the{" "}
        <Text color="$neutral1" cursor="pointer">
          Terms of Use
        </Text>{" "}
        and acknowledge that you are responsible for monitoring your own position.
      </Text>

      {
    /* Action Button */
  }
      <PrimaryActionButton onPress={handleConfirm}>
        <Button.Text>Enable Auto-Deleverage</Button.Text>
      </PrimaryActionButton>

      <Flex
    flexDirection="row"
    justifyContent="center"
    alignItems="center"
    gap="$gap8"
    mt="$spacing24"
    cursor="pointer"
  >
        <Text variant="buttonLabel3" color="$neutral2">
          How does it work?
        </Text>
        <ArrowUpRight size={14} color={colors.neutral2.val} />
      </Flex>
    </Modal>;
}
