"use strict";
import { createColumnHelper } from "@tanstack/react-table";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { Table } from "components/Table";
import { Cell } from "components/Table/Cell";
import { ClickableHeaderRow, HeaderArrow, HeaderCell, HeaderSortText, TableText } from "components/Table/styled";
import { MAX_WIDTH_MEDIA_BREAKPOINT } from "components/Tokens/constants";
import { OrderDirection } from "graphql/data/util";
import { useMorphoMarkets } from "hooks/morpho";
import { memo, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Flex, StarBorderButton, Text, styled, useMedia } from "ui/src";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { NumberType, useFormatter } from "utils/formatNumbers";
import { useBorrowContext } from "../ContextProvider";
import { BorrowSortMethod } from "../types";
import { transformMorphoMarketToBorrowData } from "../utils";
const TableWrapper = styled(Flex, {
  m: "0 auto",
  maxWidth: MAX_WIDTH_MEDIA_BREAKPOINT
});
const HEADER_TEXT = {
  [BorrowSortMethod.COLLATERAL]: "Collateral",
  [BorrowSortMethod.LOAN]: "Loan",
  [BorrowSortMethod.LLTV]: "LLTV",
  [BorrowSortMethod.MARKET_SIZE]: "Total Market Size",
  [BorrowSortMethod.LIQUIDITY]: "Total Liquidity",
  [BorrowSortMethod.RATE]: "Rate",
  [BorrowSortMethod.MANAGE]: "Manage"
};
function BorrowTableHeader({
  category,
  isCurrentSortMethod,
  direction,
  showArrow = false,
  justifyContent = "flex-end"
}) {
  const handleSortCategory = () => {
    console.log("Sort by:", category);
  };
  return <Flex width="100%">
      <ClickableHeaderRow justifyContent={justifyContent} onPress={handleSortCategory} group>
        {showArrow && <HeaderArrow orderDirection={direction} size={14} opacity={isCurrentSortMethod ? 1 : 0} />}
        <HeaderSortText active={isCurrentSortMethod} variant="body3">
          {HEADER_TEXT[category]}
        </HeaderSortText>
      </ClickableHeaderRow>
    </Flex>;
}
function BorrowTableComponent({
  borrows,
  loading,
  error,
  chainId
}) {
  const { formatFiatPrice, formatNumber, formatPercent } = useFormatter();
  const { openTransaction } = useBorrowContext();
  const [sortMethod, setSortMethod] = useState(BorrowSortMethod.MARKET_SIZE);
  const [sortAscending, setSortAscending] = useState(false);
  const orderDirection = sortAscending ? OrderDirection.Asc : OrderDirection.Desc;
  const media = useMedia();
  const TOKEN_SIZE = 24;
  const borrowTableValues = useMemo(() => {
    const tableValues = borrows?.map((borrow, i) => {
      return {
        index: i,
        collateral: <Flex row alignItems="center" gap="$gap12">
              <PortfolioLogo
          chainId={chainId}
          tokenSymbol={borrow.collateral.symbol}
          tokenName={borrow.collateral.name}
          images={[getTokenLogoUrl(borrow.collateral.tokenId)]}
          size={TOKEN_SIZE}
        />
              <TableText>{borrow.collateral.symbol}</TableText>
              {
          /* {
            borrow.collateral.symbol === 'WETH' && i === 2 && ( // Example of adding the plus icon for the specific WETH row if needed, strictly hardcoded for now or based on a property
               <PlusCircle size="$icon.16" color="$neutral3" />
            )
          } */
        }
            </Flex>,
        loan: <Flex row alignItems="center" gap="$gap12">
              <PortfolioLogo
          chainId={chainId}
          tokenSymbol={borrow.loan.symbol}
          tokenName={borrow.loan.name}
          images={[getTokenLogoUrl(borrow.loan.tokenId)]}
          size={TOKEN_SIZE}
        />
              <TableText>{borrow.loan.symbol}</TableText>
            </Flex>,
        lltv: <Flex height={"100%"} width={"100%"} my={"$spacing1"} flexDirection="column" justifyContent="center">
              <TableText textAlign="right">{borrow.lltv.toFixed(2)}%</TableText>
            </Flex>,
        marketSize: <Flex height={"100%"} width={"100%"} my={"$spacing1"} flexDirection="column" justifyContent="center">
              <Flex row gap="$gap8" justifyContent="flex-end" alignItems="center">
                <TableText textAlign="right">
                  {formatNumber({ input: borrow.marketSize.amount, type: NumberType.TokenTwoDecimals })}{" "}
                  {borrow.marketSize.symbol}
                </TableText>
                <Flex backgroundColor="$surface3" px="$spacing4" py="$spacing2" borderRadius="$rounded4">
                  <Text variant="body4" color="$neutral2">
                    {formatFiatPrice({ price: borrow.marketSize.usdValue, type: NumberType.FiatTokenStats })}
                  </Text>
                </Flex>
              </Flex>
            </Flex>,
        liquidity: <Flex height={"100%"} width={"100%"} my={"$spacing1"} flexDirection="column" justifyContent="center">
              <Flex row gap="$gap8" justifyContent="flex-end" alignItems="center">
                <TableText textAlign="right">
                  {formatNumber({ input: borrow.liquidity.amount, type: NumberType.TokenTwoDecimals })}{" "}
                  {borrow.liquidity.symbol}
                </TableText>
                <Flex backgroundColor="$surface3" px="$spacing4" py="$spacing2" borderRadius="$rounded4">
                  <Text variant="body4" color="$neutral2">
                    {formatFiatPrice({ price: borrow.liquidity.usdValue, type: NumberType.FiatTokenStats })}
                  </Text>
                </Flex>
              </Flex>
            </Flex>,
        rate: <Flex height={"100%"} width={"100%"} my={"$spacing1"} flexDirection="column" justifyContent="center">
              <TableText textAlign="right">{borrow.rate.toFixed(2)}%</TableText>
            </Flex>,
        manage: <Flex
          height={"100%"}
          width={"100%"}
          row
          justifyContent="flex-end"
          alignItems="center"
          onPress={(e) => e.stopPropagation()}
        >
              <StarBorderButton
          py={4}
          px={8}
          backgroundColor="$surface2"
          onPress={(e) => {
            e.stopPropagation();
            openTransaction(
              {
                id: borrow.marketId,
                collateral: {
                  amount: 0,
                  value: 0,
                  token: {
                    id: borrow.collateral.tokenId,
                    symbol: borrow.collateral.symbol,
                    name: borrow.collateral.name
                  }
                },
                loan: {
                  amount: 0,
                  value: 0,
                  token: {
                    id: borrow.loan.tokenId,
                    symbol: borrow.loan.symbol,
                    name: borrow.loan.name
                  }
                },
                rate: borrow.rate,
                health: "0",
                utilization: 0
              },
              "borrow"
            );
          }}
        >
                <Text variant="body3">Borrow</Text>
              </StarBorderButton>
            </Flex>,
        borrow,
        // Numeric values for sorting
        lltvValue: borrow.lltv,
        marketSizeValue: borrow.marketSize.usdValue,
        liquidityValue: borrow.liquidity.usdValue,
        rateValue: borrow.rate
      };
    }) ?? [];
    return tableValues.sort((a, b) => {
      let aValue = 0;
      let bValue = 0;
      switch (sortMethod) {
        case BorrowSortMethod.LLTV:
          aValue = a.lltvValue;
          bValue = b.lltvValue;
          break;
        case BorrowSortMethod.MARKET_SIZE:
          aValue = a.marketSizeValue;
          bValue = b.marketSizeValue;
          break;
        case BorrowSortMethod.LIQUIDITY:
          aValue = a.liquidityValue;
          bValue = b.liquidityValue;
          break;
        case BorrowSortMethod.RATE:
          aValue = a.rateValue;
          bValue = b.rateValue;
          break;
        default:
          return 0;
      }
      const comparison = bValue - aValue;
      return sortAscending ? -comparison : comparison;
    });
  }, [borrows, formatFiatPrice, formatNumber, sortMethod, sortAscending, chainId, openTransaction]);
  const showLoadingSkeleton = loading || !!error;
  const columns = useMemo(() => {
    const columnHelper = createColumnHelper();
    return [
      columnHelper.accessor((row) => row.collateral, {
        id: "collateral",
        size: 80,
        header: () => <HeaderCell justifyContent="flex-start">
            <BorrowTableHeader
          category={BorrowSortMethod.COLLATERAL}
          isCurrentSortMethod={false}
          direction={orderDirection}
          justifyContent="flex-start"
        />
          </HeaderCell>,
        cell: (collateral) => <Cell height="100%" justifyContent="flex-start" loading={showLoadingSkeleton} testId="collateral-cell">
            {collateral.getValue?.()}
          </Cell>
      }),
      columnHelper.accessor((row) => row.loan, {
        id: "loan",
        size: 80,
        header: () => <HeaderCell justifyContent="flex-start">
            <BorrowTableHeader
          category={BorrowSortMethod.LOAN}
          isCurrentSortMethod={false}
          direction={orderDirection}
          justifyContent="flex-start"
        />
          </HeaderCell>,
        cell: (loan) => <Cell height="100%" justifyContent="flex-start" loading={showLoadingSkeleton} testId="loan-cell">
            {loan.getValue?.()}
          </Cell>
      }),
      columnHelper.accessor((row) => row.lltv, {
        id: "lltv",
        header: () => <HeaderCell justifyContent="flex-end">
            <BorrowTableHeader
          category={BorrowSortMethod.LLTV}
          isCurrentSortMethod={sortMethod === BorrowSortMethod.LLTV}
          direction={orderDirection}
        />
          </HeaderCell>,
        cell: (lltv) => <Cell height="100%" loading={showLoadingSkeleton} testId="lltv-cell">
            {lltv.getValue?.()}
          </Cell>
      }),
      columnHelper.accessor((row) => row.marketSize, {
        id: "marketSize",
        size: 200,
        header: () => <HeaderCell justifyContent="flex-end">
            <BorrowTableHeader
          category={BorrowSortMethod.MARKET_SIZE}
          isCurrentSortMethod={sortMethod === BorrowSortMethod.MARKET_SIZE}
          direction={orderDirection}
        />
          </HeaderCell>,
        cell: (marketSize) => <Cell height="100%" loading={showLoadingSkeleton} testId="market-size-cell">
            {marketSize.getValue?.()}
          </Cell>
      }),
      columnHelper.accessor((row) => row.liquidity, {
        id: "liquidity",
        size: 200,
        header: () => <HeaderCell justifyContent="flex-end">
            <BorrowTableHeader
          category={BorrowSortMethod.LIQUIDITY}
          isCurrentSortMethod={sortMethod === BorrowSortMethod.LIQUIDITY}
          direction={orderDirection}
        />
          </HeaderCell>,
        cell: (liquidity) => <Cell height="100%" loading={showLoadingSkeleton} testId="liquidity-cell">
            {liquidity.getValue?.()}
          </Cell>
      }),
      columnHelper.accessor((row) => row.rate, {
        id: "rate",
        size: 80,
        header: () => <HeaderCell>
            <BorrowTableHeader
          category={BorrowSortMethod.RATE}
          isCurrentSortMethod={sortMethod === BorrowSortMethod.RATE}
          direction={orderDirection}
        />
          </HeaderCell>,
        cell: (rate) => <Cell height="100%" loading={showLoadingSkeleton} testId="rate-cell">
            {rate.getValue?.()}
          </Cell>
      }),
      columnHelper.accessor((row) => row.manage, {
        id: "manage",
        size: 120,
        header: () => <HeaderCell>
            <BorrowTableHeader
          category={BorrowSortMethod.MANAGE}
          isCurrentSortMethod={sortMethod === BorrowSortMethod.MANAGE}
          direction={orderDirection}
        />
          </HeaderCell>,
        cell: (manage) => <Cell height="100%" loading={showLoadingSkeleton} testId="manage-cell">
            {manage.getValue?.()}
          </Cell>
      })
    ];
  }, [orderDirection, showLoadingSkeleton, sortMethod]);
  const navigate = useNavigate();
  return <Table
    columns={columns}
    data={borrowTableValues ?? []}
    loading={loading}
    error={error}
    maxWidth={1200}
    tableType={"vault"}
    tableHeight={64}
    defaultPinnedColumns={["collateral"]}
    onRowClick={(row) => navigate(`/borrow/market?id=${row.borrow.marketId}`)}
  />;
}
export default memo(function BorrowTable() {
  const chainId = UniverseChainId.Mainnet;
  const { data: morphoMarkets, isLoading, isError } = useMorphoMarkets(chainId);
  const borrows = useMemo(() => {
    if (!morphoMarkets) return [];
    return morphoMarkets.map(transformMorphoMarketToBorrowData);
  }, [morphoMarkets]);
  return <TableWrapper data-testid="borrow-table">
      <BorrowTableComponent borrows={borrows} loading={isLoading} error={isError} chainId={chainId} />
    </TableWrapper>;
});
