  for (const tx of sorted) {
    const amountUsd = parseFloat(tx.amountUsd.replace(/[$,]/g, "")) || 0;
    switch (tx.type) {
      case "Borrow":
        loanDelta += amountUsd;
        loanTxAmounts.push({ tx, amount: amountUsd });
        break;
      case "Repay":
        loanDelta -= amountUsd;
        loanTxAmounts.push({ tx, amount: -amountUsd });
        break;
      case "Deposit":
        collateralDelta += amountUsd;
        collateralTxAmounts.push({ tx, amount: amountUsd });
        break;
      case "Withdraw":
        collateralDelta -= amountUsd;
        collateralTxAmounts.push({ tx, amount: -amountUsd });
        break;
    }
  }
  let collateralCorrectionFactor = 1;
  if (collateralDelta > 0 && currentCollateralUsd > 0) {
    if (collateralDelta > currentCollateralUsd * 10) {
      collateralCorrectionFactor = currentCollateralUsd / collateralDelta;
    }
  }
  let loanCorrectionFactor = 1;
  if (loanDelta > 0 && currentLoanUsd > 0) {
    if (loanDelta > currentLoanUsd * 10) {
      loanCorrectionFactor = currentLoanUsd / loanDelta;
    }
  }
  const correctedLoanDelta = loanDelta * loanCorrectionFactor;
  const correctedCollateralDelta = collateralDelta * collateralCorrectionFactor;
