"use strict";
import { motion } from "framer-motion";
import uiStyled from "styled-components";
import { Flex, Text, styled } from "ui/src";
const Container = styled(Flex, {
  row: true,
  position: "relative",
  backgroundColor: "$surface2",
  borderRadius: "9999px",
  padding: "$spacing8",
  width: "fit-content",
  alignItems: "center",
  gap: "$spacing8"
});
const ToggleItem = styled(Flex, {
  px: "$spacing16",
  py: "$spacing8",
  borderRadius: "9999px",
  cursor: "pointer",
  position: "relative",
  zIndex: 1,
  justifyContent: "center",
  alignItems: "center"
});
const Label = styled(Text, {
  transition: "color 0.2s ease",
  zIndex: 2,
  userSelect: "none"
});
const ActiveBackground = uiStyled(motion.div)`
  position: absolute;
  inset: 0;
  height: 100%;
  width: 100%;
  border-radius: 9999px;
  z-index: 0;
`;
export default function ToggleLend({
  activeTab,
  setActiveTab
}) {
  const buttons = [
    { label: "Earn", url: "/lend/earn" },
    { label: "Borrow", url: "/lend/borrow" }
  ];
  return <Flex row justifyContent="center" alignItems="center" mb={"$spacing28"}>
      <Container>
        {buttons.map((tab) => {
    const isActive = activeTab === tab.label;
    return <ToggleItem onPress={() => setActiveTab(tab.label)}>
              {isActive && <ActiveBackground
      className="active-bg-toggle"
      layoutId="activeToggle"
      transition={{
        type: "spring",
        stiffness: 500,
        damping: 30
      }}
    >
                  <Flex backgroundColor={"$neutral1"} borderRadius={"$roundedFull"} width={"100%"} height={"100%"} />
                </ActiveBackground>}
              <Label variant="subheading1" color={isActive ? "$surface2" : "$neutral2"}>
                {tab.label}
              </Label>
            </ToggleItem>;
  })}
      </Container>
    </Flex>;
}
