"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { useMorphoMarkets, useMorphoUserBorrowPosition } from "hooks/morpho";
import { useState } from "react";
import { ArrowUpRight, X } from "react-feather";
import { Button, Flex, Input, SpinningLoader, Text, styled as uiStyled, useSporeColors } from "ui/src";
import { Modal } from "uniswap/src/components/modals/Modal";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { useAccount } from "wagmi";
import { useBorrowContext } from "../ContextProvider";
const CloseIcon = uiStyled(Flex, {
  cursor: "pointer",
  padding: "$spacing8",
  borderRadius: "$roundedFull",
  hoverStyle: { backgroundColor: "$surface2" }
});
const ModalHeader = uiStyled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing24"
});
const InputCard = uiStyled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing16",
  gap: "$gap12",
  width: "100%",
  transition: "border-color 0.2s ease-in-out",
  borderWidth: 1,
  borderColor: "$surface3",
  variants: {
    focused: {
      true: {
        borderColor: "$neutral3"
      }
    }
  },
  marginBottom: "$spacing16"
});
const InputField = uiStyled(Input, {
  unstyled: true,
  backgroundColor: "transparent",
  borderWidth: 0,
  outlineStyle: "none",
  padding: 0,
  fontSize: "$h3",
  color: "$neutral1",
  width: "100%",
  textAlign: "left",
  fontFamily: "$body3"
});
const MaxButton = uiStyled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$rounded8",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8",
  cursor: "pointer",
  hoverStyle: { opacity: 0.8 }
});
const InfoCard = uiStyled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing24",
  flexDirection: "column",
  gap: "$spacing12",
  width: "100%",
  marginBottom: "$spacing24"
});
const InfoRow = uiStyled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%"
});
const ActionButton = uiStyled(Button, {
  width: "100%",
  borderRadius: "$roundedFull",
  py: "$spacing20",
  variants: {
    disabled: {
      true: {
        backgroundColor: "$surface3",
        color: "$neutral2",
        cursor: "not-allowed"
      },
      false: {
        backgroundColor: "$neutral1",
        color: "$surface1"
      }
    }
  }
});
const OverlappingLogos = uiStyled(Flex, {
  flexDirection: "row",
  position: "relative",
  width: 64,
  height: 40
});
const LogoWrapper = uiStyled(Flex, {
  position: "absolute",
  borderRadius: "$roundedFull",
  borderWidth: 2,
  borderColor: "$surface2",
  overflow: "hidden"
});
const Badge = uiStyled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  px: "$spacing8",
  py: "$spacing2",
  alignItems: "center",
  justifyContent: "center"
});
export default function BorrowPopupModal({
  position,
  isOpen,
  onClose
}) {
  const { collateralAmount, setCollateralAmount, borrowAmount, setBorrowAmount, setTransactionStep } = useBorrowContext();
  const [focusedInput, setFocusedInput] = useState(null);
  const colors = useSporeColors();
  const chainId = UniverseChainId.Mainnet;
  const { address: userAddress } = useAccount();
  const marketId = position?.id;
  const { data: userPosition, isLoading: isLoadingPosition } = useMorphoUserBorrowPosition(
    marketId,
    userAddress,
    chainId
  );
  const { data: markets } = useMorphoMarkets(chainId);
  if (!position) return null;
  const market = markets?.find((m) => m.id.toLowerCase() === marketId?.toLowerCase());
  const collateralToken = position.collateral.token;
  const borrowToken = position.loan.token;
  const collateralBalanceRaw = userPosition?.walletCollateralBalanceFormatted ?? "0";
  const collateralBalanceDisplay = Number(collateralBalanceRaw);
  const liquidationLtv = userPosition?.lltvPercent ?? 86;
  const rate = market?.borrowRate ?? 0;
  const existingCollateral = Number(userPosition?.collateralFormatted ?? "0");
  const existingLoan = Number(userPosition?.borrowAssetsFormatted ?? "0");
  const availableLiquidity = Number(market?.availableLiquidityFormatted ?? "0");
  const parsedCollateral = parseFloat(collateralAmount) || 0;
  const parsedBorrow = parseFloat(borrowAmount) || 0;
  const collateralPriceUsd = market?.collateralPriceUsd ?? 0;
  const loanPriceUsd = market?.loanPriceUsd ?? 1;
  const collateralUsd = parsedCollateral * collateralPriceUsd;
  const borrowUsd = parsedBorrow * loanPriceUsd;
  const ltv = userPosition?.ltv ?? 0;
  const maxBorrowableByCollateral = (() => {
    const totalCollateralAfter = existingCollateral + parsedCollateral;
    const collateralValueUsd = totalCollateralAfter * collateralPriceUsd;
    const maxBorrowUsd = collateralValueUsd * (liquidationLtv / 100) * 0.95;
    const maxBorrowAmount = maxBorrowUsd / loanPriceUsd - existingLoan;
    return Math.max(0, maxBorrowAmount);
  })();
  const maxBorrowable = Math.min(maxBorrowableByCollateral, availableLiquidity);
  const borrowExceedsLiquidity = parsedBorrow > availableLiquidity;
  const borrowExceedsCollateralLimit = parsedBorrow > maxBorrowableByCollateral;
  const supplyExceedsBalance = parsedCollateral > collateralBalanceDisplay;
  const getValidationError = () => {
    if (supplyExceedsBalance) return `Insufficient ${collateralToken.symbol} balance`;
    if (parsedBorrow > 0 && existingCollateral === 0 && parsedCollateral === 0)
      return "Add collateral to enable borrowing";
    if (borrowExceedsLiquidity)
      return `Only ${availableLiquidity.toFixed(4)} ${borrowToken.symbol} available in market`;
    if (borrowExceedsCollateralLimit)
      return `Max borrowable: ${maxBorrowableByCollateral.toFixed(4)} ${borrowToken.symbol}`;
    return null;
  };
  const validationError = getValidationError();
  const isFormValid = (parsedCollateral > 0 || parsedBorrow > 0) && !validationError;
  const actionText = validationError ? validationError : isFormValid ? "Borrow" : "Enter an amount";
  const handleConfirm = () => {
    setTransactionStep("review");
  };
  const handleClose = () => {
    setCollateralAmount("");
    setBorrowAmount("");
    onClose();
  };
  return <Modal
    name={"BorrowPopupModal"}
    isModalOpen={isOpen}
    onClose={handleClose}
    backgroundColor={colors.surface1?.val ?? "#1a1a1a"}
    maxWidth={480}
    padding="$spacing24"
  >
      {
    /* Header */
  }
      <ModalHeader>
        <Text variant="heading2" color="$neutral1">
          Borrow
        </Text>
        <CloseIcon onPress={handleClose}>
          <X size={24} color={colors.neutral2?.val ?? "#888"} />
        </CloseIcon>
      </ModalHeader>

      {
    /* Supply Section */
  }
      <Flex flexDirection="row" justifyContent="space-between" mb="$spacing8" px="$spacing4">
        <Text variant="body3" color="$neutral2">
          Supply {collateralToken.symbol} collateral
        </Text>
        <Flex flexDirection="row" gap="$gap8" alignItems="center">
          {isLoadingPosition ? <SpinningLoader size={16} /> : <Text variant="body3" color="$neutral2">
              {collateralBalanceDisplay.toFixed(4)} {collateralToken.symbol}
            </Text>}
          <MaxButton onPress={() => setCollateralAmount(collateralBalanceRaw)}>
            <Text variant="buttonLabel4" color="$neutral2">
              MAX
            </Text>
          </MaxButton>
        </Flex>
      </Flex>

      <InputCard focused={focusedInput === "supply"}>
        <Flex flexDirection="row" alignItems="center" justifyContent="space-between">
          <InputField
    placeholder="0.00"
    placeholderTextColor="$neutral3"
    value={collateralAmount}
    onChangeText={setCollateralAmount}
    onFocus={() => setFocusedInput("supply")}
    onBlur={() => setFocusedInput(null)}
  />
          <Flex flexDirection="row" alignItems="center" gap="$gap8">
            <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.name ?? ""}
    images={[getTokenLogoUrl(collateralToken.id) || void 0]}
    size={24}
  />
            <Text variant="body1" color="$neutral1">
              {collateralToken.symbol}
            </Text>
          </Flex>
        </Flex>
        <Text variant="body3" color="$neutral3">
          ${collateralUsd.toFixed(2)}
        </Text>
      </InputCard>

      {
    /* Borrow Section */
  }
      <Flex flexDirection="row" justifyContent="space-between" mb="$spacing8" mt="$spacing4" px="$spacing4">
        <Text variant="body3" color="$neutral2">
          Borrow {borrowToken.symbol}
        </Text>
        <Flex flexDirection="row" gap="$gap8" alignItems="center">
          {isLoadingPosition ? <SpinningLoader size={16} /> : <Text variant="body3" color="$neutral2">
              Max: {maxBorrowable.toFixed(4)} {borrowToken.symbol}
            </Text>}
          <MaxButton
    onPress={() => {
      if (maxBorrowable > 0) {
        const conservativeMax = Math.floor(maxBorrowable * 1e6) / 1e6;
        setBorrowAmount(conservativeMax.toFixed(6));
      }
    }}
  >
            <Text variant="buttonLabel4" color="$neutral2">
              MAX
            </Text>
          </MaxButton>
        </Flex>
      </Flex>

      <InputCard focused={focusedInput === "borrow"}>
        <Flex flexDirection="row" alignItems="center" justifyContent="space-between">
          <InputField
    placeholder="0.00"
    placeholderTextColor="$neutral3"
    value={borrowAmount}
    onChangeText={setBorrowAmount}
    onFocus={() => setFocusedInput("borrow")}
    onBlur={() => setFocusedInput(null)}
  />
          <Flex flexDirection="row" alignItems="center" gap="$gap8">
            <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={borrowToken.symbol}
    tokenName={borrowToken.name ?? ""}
    images={[getTokenLogoUrl(borrowToken.id) || void 0]}
    size={24}
  />
            <Text variant="body1" color="$neutral1">
              {borrowToken.symbol}
            </Text>
          </Flex>
        </Flex>
        <Text variant="body3" color="$neutral3">
          ${borrowUsd.toFixed(2)}
        </Text>
      </InputCard>

      {
    /* Info Card */
  }
      <InfoCard>
        <Flex flexDirection="row" alignItems="center" gap="$gap16" mb="$spacing8">
          <OverlappingLogos>
            <LogoWrapper left={0} zIndex={2}>
              <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.name ?? ""}
    images={[getTokenLogoUrl(collateralToken.id) || void 0]}
    size={40}
  />
            </LogoWrapper>
            <LogoWrapper left={24} zIndex={1}>
              <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={borrowToken.symbol}
    tokenName={borrowToken.name ?? ""}
    images={[getTokenLogoUrl(borrowToken.id) || void 0]}
    size={40}
  />
            </LogoWrapper>
          </OverlappingLogos>
          <Flex flexDirection="column" gap="$gap4">
            <Text variant="heading3" color="$neutral1">
              {collateralToken.symbol}/{borrowToken.symbol}
            </Text>
            <Flex flexDirection="row" gap="$gap8" alignItems="center">
              <Badge>
                <Text variant="body4" color="$neutral2">
                  {liquidationLtv}%
                </Text>
              </Badge>
              <ArrowUpRight size={14} color={colors.neutral2?.val ?? "#888"} />
            </Flex>
          </Flex>
        </Flex>

        <InfoRow>
          <Flex flexDirection="row" alignItems="center" gap="$gap8">
            <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.name ?? ""}
    images={[getTokenLogoUrl(collateralToken.id) || void 0]}
    size={16}
  />
            <Text variant="body3" color="$neutral2">
              Collateral ({collateralToken.symbol})
            </Text>
          </Flex>
          <Text variant="body3" color="$neutral1">
            {position.collateral.amount.toFixed(1)}
          </Text>
        </InfoRow>

        <InfoRow>
          <Flex flexDirection="row" alignItems="center" gap="$gap8">
            <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={borrowToken.symbol}
    tokenName={borrowToken.name ?? ""}
    images={[getTokenLogoUrl(borrowToken.id) || void 0]}
    size={16}
  />
            <Text variant="body3" color="$neutral2">
              Loan ({borrowToken.symbol})
            </Text>
          </Flex>
          <Text variant="body3" color="$neutral1">
            {position.loan.amount.toFixed(0)}
          </Text>
        </InfoRow>

        <InfoRow>
          <Text variant="body3" color="$neutral2">
            LTV
          </Text>
          <Text variant="body3" color="$neutral1">
            {ltv}%
          </Text>
        </InfoRow>

        <InfoRow>
          <Text variant="body3" color="$neutral2">
            Liquidation LTV
          </Text>
          <Text variant="body3" color="$neutral1">
            {liquidationLtv}%
          </Text>
        </InfoRow>

        <InfoRow>
          <Text variant="body3" color="$neutral2">
            Rate
          </Text>
          <Text variant="body3" color="$neutral1">
            {rate}%
          </Text>
        </InfoRow>
      </InfoCard>

      {
    /* Action Button */
  }
      <ActionButton disabled={!isFormValid} onPress={handleConfirm}>
        <Button.Text>{actionText}</Button.Text>
      </ActionButton>
    </Modal>;
}
